var QQ_GROUP = "1097919737";
var MAKER_QQ = "1820480783";
var DEF_DOMAIN = "bl-novel.com";
function base(){
	var dom = source.get("base") || "";
	if(!dom){ dom = DEF_DOMAIN; try{ source.put("base", dom); }catch(e){} }
	return "https://" + dom;
}
function isAlive(dom){
	try{
		var t = String(java.ajax("https://" + dom + "/") || "");
		return t.length > 200 && (t.indexOf("BL小说") >= 0 || t.indexOf("耽美") >= 0);
	}catch(e){ return false; }
}
function login(){
	// 右上角 ✓：只保存设置，不跳转
	try{ java.upLoginData(); }catch(e){}
	java.toast("设置已保存，需要登录请点「👤 登录」");
}
function doLogin(){
	// 网页登录
	try{
		java.startBrowserAwait(base() + "/user/", "BL小说 登录");
		var page = String(java.ajax(base() + "/user/") || "");
		if(page.indexOf("退出登录") >= 0 || page.indexOf("个人中心") >= 0 || page.indexOf("member/logout") >= 0){
			java.longToast("✅ 登录成功");
		}else{
			java.longToast("⚠️ 未检测到登录状态，请重新点「👤 登录」");
		}
	}catch(e){ java.longToast("登录未完成：" + e); }
}
function checkLogin(){
	var login = false;
	try{
		var page = String(java.ajax(base() + "/user/") || "");
		login = page.indexOf("退出登录") >= 0 || page.indexOf("个人中心") >= 0 || page.indexOf("member/logout") >= 0;
	}catch(e){}
	java.longToast(login ? "✅ 已登录" : "❌ 未登录");
}
function checkDomain(){
	var dom = source.get("base") || DEF_DOMAIN;
	var alive = isAlive(dom);
	java.longToast("🌐 当前域名：" + dom + (alive ? "（可用）" : "（不可用，请在域名列表切换）"));
}
function switchDomain(){
	var sel = "";
	try{ sel = String(result["域名列表"] || (result.get && result.get("域名列表")) || ""); }catch(e){}
	if(!sel){ java.longToast("请先在域名列表选择域名"); return; }
	if(isAlive(sel)){
		try{ source.put("base", sel); }catch(e){}
		java.longToast("🌐 已切换域名：" + sel);
		try{ java.refreshExplore(); }catch(e){}
	}else{
		java.longToast("⚠️ 该域名不可用（证书/网络问题）：" + sel);
	}
}
function logoff(){
	try{
		try{ java.ajax(base() + "/member/logout"); }catch(e){}
		try{ cookie.removeCookie(base()); }catch(e){}
		java.toast("已退出登录");
	}catch(e){ java.toast("退出失败：" + e); }
}
